const lockCompanyOpsAssignmentCommand = `-- name: LockCompanyOpsAssignmentCommand :exec
SELECT pg_advisory_xact_lock(hashtextextended(
	concat(
		CAST($1 AS uuid),
		':',
		CAST($2 AS uuid)
	),
    0
))
`

